/usr/bin/zsh -lc "node --input-type=module <<'NODE'
import puppeteer from '/tmp/qs-hf-probe/node_modules/puppeteer-core/lib/puppeteer/puppeteer-core.js';
import {readFile,writeFile} from 'node:fs/promises';
const browser = await puppeteer.launch({executablePath:'/home/djn12313/.cache/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-linux64/chrome-headless-shell',headless:true,args:['--no-sandbox','--disable-background-networking']});
try {
 const report = JSON.parse(await readFile('evidence/browser-observations.json','utf8'));
 const page=await browser.newPage();
 await page.setRequestInterception(true);
 page.on('request',r=>r.url().startsWith('file:')?r.continue():r.abort());
 report.layouts=[];
 for(const [name,width,height,theme] of [['wide',1280,900,'light'],['narrow',390,844,'light'],['wide-dark',1280,900,'dark'],['narrow-dark',390,844,'dark']]){
  await page.setViewport({width,height});
  await page.emulateMediaFeatures([{name:'prefers-color-scheme',value:theme}]);
  await page.goto('file:///tmp/qs-frontend-trial-LMGCAx/index.html');
  await page.screenshot({path:"'`evidence/${name}.png`,fullPage:true});
  report.layouts.push(await page.evaluate(name=>{
   function luminance(hex){const a=hex.trim().replace('"'#','').match(/../g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return a[0]*.2126+a[1]*.7152+a[2]*.0722;}
   const css=getComputedStyle(document.documentElement);
   function contrast(a,b){const l=[a,b].map(x=>luminance(css.getPropertyValue(x))).sort((a,b)=>b-a);return Number(((l[0]+.05)/(l[1]+.05)).toFixed(2));}
   return {name,width:innerWidth,documentWidth:document.documentElement.scrollWidth,headline:document.querySelector('h1').textContent,headerHeight:document.querySelector('header').getBoundingClientRect().height,buttonBottom:document.querySelector('button').getBoundingClientRect().bottom,buttonContrast:contrast('--accent','--button-text'),helperContrast:contrast('--muted','--surface'),linkContrast:contrast('--accent','--surface'),placeholderContrast:contrast('--muted','--input')};
  },name));
 }
 await page.type('#member-email','family@example.com');await page.focus('#join-button');await page.keyboard.press('Enter');
 await page.screenshot({path:'evidence/narrow-success-dark.png',fullPage:true});
 report.finalFormCheck=await page.evaluate(()=>({events:window.__events,message:document.querySelector('#form-message').textContent}));
 await writeFile('evidence/browser-observations.json',JSON.stringify(report,null,2));
 console.log(JSON.stringify(report.layouts,null,2));
} finally {await browser.close();}
NODE"
